/// <reference types="cypress" />
/// <reference types="@testing-library/cypress" />
/**
 * Shared Cypress commands for the omnicore-platform e2e suite.
 *
 *   cy.login(persona)      authed session via cy.session (cached across specs),
 *                          driving the real Keycloak OIDC PKCE flow through
 *                          cy.origin. This is the canonical way to be logged in.
 *   cy.loginFresh(opts)    one-shot login for a FRESH unique user, no session
 *                          cache — for the force-change-password journey.
 *   cy.skipIfStackDown()   yields true when the live stack is down (so a spec can
 *                          skip); the global before() in e2e.ts is the primary guard.
 *
 * i18n rule: use @testing-library/cypress semantic queries (findByRole/Text/Label)
 * on OUR pages. Raw CSS (input[name=...]) is only used inside cy.origin on
 * Keycloak's own login page, which is not part of our translated surface.
 */
import type { PersonaId } from "./personas";
import { DEFAULT_E2E_PASSWORD } from "./credentials";

export interface PersonaCreds {
  persona: string;
  email: string;
  password: string;
  orgId: string | null;
  kcUserId: string;
  realmRoles: string[];
  degraded: boolean;
}

export interface LoginFreshOptions {
  email?: string;
  password?: string;
  /** When true, the user must change password on first login (UPDATE_PASSWORD). */
  passwordChangeRequired?: boolean;
  /** Optional omnicore_org_id attribute. */
  orgId?: string;
  /** Stop after the Keycloak credential step (default true) — the spec then
   *  drives whatever comes next (change-password form, dashboard, redirect). */
  stopAfterCredentials?: boolean;
}

function keycloakOrigin(): string {
  return (Cypress.env("KEYCLOAK_URL") as string) ?? "http://localhost:8080";
}

function shellBffUrl(): string {
  return (Cypress.env("SHELL_BFF_URL") as string) ?? "http://localhost:8082";
}

/**
 * The host:port the OIDC round-trip must land back on, derived from the
 * configured baseUrl rather than hardcoded.
 *
 * For the default `http://localhost:5173` this is exactly `localhost:5173`,
 * so the primary-stack behaviour is unchanged. Deriving it is what lets the
 * suite run against a walled local stack (`make up STACK=<name>`), whose app
 * origin is `<name>.localhost:<probed-port>` — a hardcoded host failed every
 * cy.login() there, which meant the walled-stack feature shipped with no way
 * to run Cypress against it.
 */
function shellHost(): string {
  return new URL(Cypress.config("baseUrl") as string).host;
}

/**
 * Enter credentials on Keycloak's own login form, inside cy.origin. This is the
 * single source of truth for the login-page interaction — shared by performLogin
 * and loginFresh so a markup change on Keycloak's form is fixed in one place.
 * Raw CSS selectors are intentional here: Keycloak's page is not our translated
 * surface (see the i18n note in the file header).
 */
function submitKeycloakCredentials(email: string, password: string): void {
  cy.origin(
    keycloakOrigin(),
    { args: { email, password } },
    ({ email, password }) => {
      cy.get("input[name=username]", { timeout: 20_000 }).clear().type(email);
      cy.get("input[name=password]").clear().type(password, { log: false });
      cy.get("input[type=submit], button[type=submit]").click();
    },
  );
}

/**
 * Drive the browser OIDC login: shell /login -> "Sign in" -> Keycloak form ->
 * back on the shell origin. Does NOT assert a specific landing path (realm
 * admins land on /admin, org users on /), only that we left Keycloak and are
 * back on the shell host and off /login.
 */
function performLogin(email: string, password: string): void {
  cy.visit("/");
  cy.location("pathname", { timeout: 20_000 }).should("match", /\/login(\/|$)/);
  cy.findByRole("button", { name: /sign in/i }).click();

  submitKeycloakCredentials(email, password);

  cy.location("host", { timeout: 30_000 }).should("eq", shellHost());
  cy.location("pathname", { timeout: 30_000 }).should("not.match", /\/login(\/|$)/);
}

Cypress.Commands.add("login", (persona: PersonaId) => {
  cy.task<PersonaCreds>("mintPersona", { persona }).then((creds) => {
    cy.session(
      persona,
      () => {
        performLogin(creds.email, creds.password);
      },
      {
        cacheAcrossSpecs: true,
        validate() {
          cy.request({
            url: "/api/v1/session",
            failOnStatusCode: false,
          })
            .its("status")
            .should("eq", 200);
        },
      },
    );
    // Yield the creds so the caller can assert on email/org/etc.
    cy.wrap(creds, { log: false });
  });
});

Cypress.Commands.add("loginFresh", (opts: LoginFreshOptions = {}) => {
  const email = opts.email ?? `fresh-${Date.now()}@e2e.local`;
  const password = opts.password ?? DEFAULT_E2E_PASSWORD;
  const stopAfterCredentials = opts.stopAfterCredentials ?? true;

  cy.task<string>("kcCreateUser", {
    email,
    password,
    passwordChangeRequired: opts.passwordChangeRequired ?? false,
    orgId: opts.orgId,
  }).then((kcUserId) => {
    cy.visit("/");
    cy.location("pathname", { timeout: 20_000 }).should("match", /\/login(\/|$)/);
    cy.findByRole("button", { name: /sign in/i }).click();
    submitKeycloakCredentials(email, password);
    // When a password change is NOT required and the spec wants a completed
    // login, wait until we are back on the shell origin. Otherwise leave the
    // browser wherever Keycloak landed (e.g. the update-password form) for the
    // spec to drive.
    if (!stopAfterCredentials && !opts.passwordChangeRequired) {
      cy.location("host", { timeout: 30_000 }).should("eq", shellHost());
    }
    cy.wrap({ email, password, kcUserId }, { log: false });
  });
});

Cypress.Commands.add("skipIfStackDown", () => {
  return cy
    .request({
      url: `${shellBffUrl()}/healthz`,
      failOnStatusCode: false,
      timeout: 5_000,
    })
    .then((res) => res.status !== 200);
});

export interface ParticipantSurfaceResult {
  exerciseId: string;
  characterId: string;
  handle: string;
}

/**
 * Provision a participant (exercise + synthetic character + credential), log the
 * credential into `surface` (kite | commons), and plant the returned session
 * cookie so the spec can drive the standalone participant surface. Yields the
 * exercise + character + handle. `domain` defaults to the current host — set it
 * (or a KITE_MFE_URL/COMMONS_MFE_URL origin) when the surface is served on a
 * different host; the cookie's Path is scoped to /api/v1/<surface> (matching
 * range-bff), so the spec must operate on an origin where /api/v1/<surface> is
 * same-origin.
 */
function loginParticipant(
  surface: "kite" | "commons",
  opts: SeedXParticipantOptions & { domain?: string } = {},
): Cypress.Chainable<ParticipantSurfaceResult> {
  return cy
    .task<import("../tasks/participant").SeedXParticipantResult>(
      "seedXParticipant",
      {
        instructorPersona: opts.instructorPersona,
        exerciseName: opts.exerciseName,
        username: opts.username,
        displayName: opts.displayName,
      },
    )
    .then((p) => {
      return cy
        .task<import("../tasks/participant").ParticipantCookie>("participantLogin", {
          surface,
          exerciseId: p.exerciseId,
          handle: p.handle,
          password: p.password,
        })
        .then((cookie) => {
          const setOpts: Partial<Cypress.SetCookieOptions> = {
            path: cookie.path,
            httpOnly: true,
            secure: true,
            sameSite: "lax",
          };
          if (opts.domain) setOpts.domain = opts.domain;
          cy.setCookie(cookie.name, cookie.value, setOpts);
          return cy.wrap(
            { exerciseId: p.exerciseId, characterId: p.characterId, handle: p.handle },
            { log: false },
          );
        });
    });
}

export interface SeedXParticipantOptions {
  instructorPersona?: string;
  exerciseName?: string;
  username?: string;
  displayName?: string;
}

Cypress.Commands.add(
  "loginParticipantX",
  (opts: SeedXParticipantOptions & { domain?: string } = {}) =>
    loginParticipant("kite", opts),
);

Cypress.Commands.add(
  "loginParticipantCommons",
  (opts: SeedXParticipantOptions & { domain?: string } = {}) =>
    loginParticipant("commons", opts),
);

declare global {
  // eslint-disable-next-line @typescript-eslint/no-namespace
  namespace Cypress {
    interface Chainable {
      /**
       * Log in as a catalog persona via cy.session (cached across specs) driving
       * the real Keycloak OIDC flow. Yields the persona's PersonaCreds.
       */
      login(persona: PersonaId): Chainable<PersonaCreds>;
      /**
       * One-shot login as a fresh unique Keycloak user (no session cache). Yields
       * { email, password, kcUserId }. For the force-change-password journey.
       */
      loginFresh(
        opts?: LoginFreshOptions,
      ): Chainable<{ email: string; password: string; kcUserId: string }>;
      /** Yields true when the live stack (shell-bff /healthz) is unreachable. */
      skipIfStackDown(): Chainable<boolean>;
      /**
       * Provision a Kite participant (exercise + synthetic character +
       * credential), log in, and plant the kite_session cookie. Yields
       * { exerciseId, characterId, handle }. Default instructor persona P6.
       */
      loginParticipantX(
        opts?: SeedXParticipantOptions & { domain?: string },
      ): Chainable<ParticipantSurfaceResult>;
      /**
       * Commons analogue of loginParticipantX — plants the commons_session cookie
       * (same participant credential authenticates both surfaces).
       */
      loginParticipantCommons(
        opts?: SeedXParticipantOptions & { domain?: string },
      ): Chainable<ParticipantSurfaceResult>;
    }
  }
}

export {};


