/**
 * Shared semantic selectors for the shell chrome. Prefer role/label/text queries
 * (i18n rule: never getByTestId for translated strings). Extend as tranches land.
 */

/** The topbar user-menu trigger button. */
export function userMenuButton(): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.findByRole("button", { name: /user menu/i });
}

/** The opened user-menu dropdown. */
export function userMenu(): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.findByRole("menu", { name: /user menu/i });
}

/** The topbar hamburger trigger that opens the primary nav (ORGANIZE) menu. */
export function navMenuTrigger(): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.findByRole("button", { name: /open navigation menu/i });
}

/** The opened primary-navigation dialog. */
export function navMenuDialog(): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.findByRole("dialog", { name: /primary navigation/i });
}

/**
 * A named section list (e.g. "organize") within the open primary-navigation
 * dialog. Each section renders as a `<ul>` (implicit role "list")
 * `aria-labelledby` its own `<h3>` heading, so the accessible name is the
 * section title (PrimaryNavMenu.tsx).
 */
export function navSectionList(
  name: string | RegExp,
): Cypress.Chainable<JQuery<HTMLElement>> {
  const matcher =
    name instanceof RegExp ? name : new RegExp(name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), "i");
  return navMenuDialog().findByRole("list", { name: matcher });
}

/**
 * Monitor Trends — the searchable MonitorRail (#2775) that replaced the native
 * `<select id="monitor-trends-selector">`. The "Your trend monitors" list is a
 * `role="radiogroup"` (accessible name "Your trend monitors", shared with the
 * section region via its sr-only <h2>) whose rows are `role="radio"` buttons
 * whose accessible name is the monitor NAME followed by its meta line
 * ("<name> · <platform> · <cadence>"). Selection is expressed as
 * aria-checked="true" on the row, replacing the old `option:selected` check.
 */

/** The rail's radiogroup list of monitors. */
export function monitorRailList(): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.findByRole("radiogroup", { name: /your trend monitors/i });
}

/**
 * A single monitor row in the rail, matched by NAME as a substring of the row's
 * accessible name (name + meta line). `timeout` covers the list refetch after a
 * create. Assert selection with `.should("have.attr", "aria-checked", "true")`.
 */
export function monitorRailRow(
  name: string,
  timeout = 30_000,
): Cypress.Chainable<JQuery<HTMLElement>> {
  const matcher = new RegExp(name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
  return monitorRailList().findByRole("radio", { name: matcher, timeout });
}

/**
 * Range wizard — Location step. StepLocationObjective.tsx has no
 * data-testids; Country/Region/City are addressed by their fixed DOM ids,
 * which stay stable across the combobox-vs-plain-input branch (e.g. Region
 * becomes a plain `<input>` for the ~45 countries with no subdivisions, but
 * keeps the same id either way).
 */

/** The wizard Region field (`#wizard-location-region`) — combobox or plain input. */
export function locationRegionField(): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.get("#wizard-location-region");
}

/** The wizard City field (`#wizard-location-city`). */
export function locationCityField(): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.get("#wizard-location-city");
}

/**
 * A city suggestion row in the open City combobox listbox, by exact visible
 * name. Suggestions render as cmdk `Combobox.Item`s (`role="option"`); the
 * row's own "selected" check icon is `aria-hidden`, so the accessible name is
 * just the city text.
 */
export function citySuggestionOption(
  city: string,
): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.findByRole("option", { name: city });
}

/**
 * A country quick-select chip, by exact visible country name (e.g. "United
 * States"). Chip renders a native `<button>`; this text is deliberately
 * pinned English in the component (see COUNTRIES_QUICK), never localized.
 */
export function countryQuickSelectChip(
  country: string,
): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.findByRole("button", { name: country });
}

/**
 * The "Optional" pill rendered next to a skippable wizard-rail step (ticket
 * #2119 — WizardNav.tsx tags each `skippable: true` WIZARD_STEPS entry:
 * factions, analysis, timeline, context). Addressed by data-testid rather
 * than the translated "Optional" text (i18n key `range_wizard_step_optional`)
 * per the i18n rule at the top of this file, so the assertion survives locale
 * switches. `stepId` matches a WIZARD_STEPS `id` (e.g. "factions", "config").
 */
export function wizardNavOptionalTag(
  stepId: string,
): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.get(`[data-testid="wizard-nav-optional-${stepId}"]`);
}

/**
 * Frame-in-shell (Task 9, #2841) — the range browser toolbar/omnibox/tab
 * queries the Frame Cypress lane shares with any future in-shell platform
 * spec. Kept generic (not Frame-specific naming) since Kite/Commons already
 * have the identical shapes and a future spec should reuse these rather than
 * re-deriving them.
 */

/**
 * The browser-shell omnibox address input (`Omnibox.tsx`), named via its
 * fixed `aria-label`/placeholder (`range_browser_omnibox_placeholder`,
 * "Search or type a web address" — never localized-per-test, since specs
 * pin the locale to en-US via `visitRange`).
 */
export function omnibox(): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.findByRole("textbox", {
    name: "Search or type a web address",
  });
}

/**
 * A tab chip in the title-bar `TabStrip` (`role="tab"`), matched by the fake
 * domain it carries (e.g. `browserTab("frame")` for the "frame.range" chip).
 * `TabChip.tsx` renders the domain as `<span>{domain}.range</span>` alongside
 * a `Lock` glyph (aria-hidden) and a "Close tab" button, so the tab's
 * accessible name is composed from more than just the domain text — a
 * substring `RegExp` (not an exact string) is what survives that.
 */
export function browserTab(domain: string): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.findByRole("tab", { name: new RegExp(domain) });
}

/**
 * The federated Frame surface's own landmark — `FrameLayout.tsx` wraps its
 * content in `<section aria-label={m.frame_app_name()}>` ("Frame"), which
 * exposes an implicit ARIA "region" role with that accessible name.
 */
export function frameSurface(): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.findByRole("region", { name: "Frame" });
}

/**
 * A toolbar platform-launcher button (`KitePlatformButton`,
 * `CommonsPlatformButton`, `FramePlatformButton`, …), by its exact
 * accessible name (e.g. `platformButton("Open Frame")`). Each renders a
 * plain `<button aria-label={m.range_browser_<platform>_platform()}>` and
 * returns `null` (no DOM node at all) when its platform is disabled —
 * `.should("not.exist")` against this selector is the disabled-platform
 * assertion.
 */
export function platformButton(
  label: string,
): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.findByRole("button", { name: label });
}

/**
 * Frame's category filter rail (#2955, `CategoryRail.tsx`) — a
 * `role="group"` named "Filter by category" wrapping one `aria-pressed`
 * chip per category.
 */
export function categoryRail(): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.findByRole("group", { name: "Filter by category" });
}

/** One chip inside `categoryRail()`, by its exact accessible name. */
export function categoryChip(name: string): Cypress.Chainable<JQuery<HTMLElement>> {
  return categoryRail().findByRole("button", { name });
}

/**
 * Frame's browse-page Trending rail (#2957, `TrendingRail.tsx`) — an
 * `<aside aria-label="Trending videos">`, exposing an implicit ARIA
 * "complementary" landmark role with that accessible name
 * (`frame_trending_rail_label`).
 */
export function trendingRail(): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.findByRole("complementary", { name: "Trending videos" });
}

/**
 * Range wizard — template picker (T14/T15/T18). `TemplatePickerModal` is a
 * single dialog (Dialog.Title text `range_wizard_template_title`, "Browse
 * templates") holding two sections: the ODIN catalog
 * (`OdinTemplatePickerModal`) first, then the curated proven-scenario
 * starters. Both grids are `<ul>`s with distinct `aria-label`s.
 */

/** The template-picker dialog itself. */
export function templatePickerDialog(): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.findByRole("dialog", { name: "Browse templates" });
}

/** The ODIN catalog grid (`aria-label` = `range_odin_template_grid_aria_label`). */
export function odinTemplateGrid(): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.findByRole("list", {
    name: "ODIN operational environment catalog",
  });
}

/** One ODIN card, by its exact accessible name (`aria-label` = template name). */
export function odinTemplateCard(
  name: string,
): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.findByRole("button", { name });
}

/**
 * The ODIN catalog's name-search `<input>`. `type="text"` (not `"search"`)
 * so it exposes role "textbox", named via `aria-label`
 * (`range_odin_template_search_aria_label`).
 */
export function odinTemplateSearchInput(): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.findByRole("textbox", {
    name: "Search ODIN operational environments",
  });
}

/**
 * The ODIN catalog's native region `<select>` (6 options: All + 5
 * geographic + "Training centers"). Named via its wrapping `<label>` text
 * ("Region"), not a `for`-linked id.
 */
export function odinTemplateRegionSelect(): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.findByRole("combobox", { name: "Region" });
}

/**
 * ExerciseOverviewRoute's header participant-count metadata item (issue
 * #2183). `MetaItem` renders a plain `<div className="flex items-center
 * gap-1.5">` with no distinguishing role/label/testid of its own — every
 * metadata segment in that row (dates, location, timezone, creator,
 * participants) shares the exact same wrapper markup, and several of them
 * are conditionally rendered, so positional indexing (the ticket's own
 * `div.flex.items-center:nth-of-type(4)`) is fragile and was the fragile
 * path this suite is meant to replace.
 *
 * Anchor on the ONE thing that IS stable without touching range-mfe: the
 * `lucide-users` class lucide-react itself stamps onto the icon's `<svg>`
 * (see `createLucideIcon` — every lucide icon gets `lucide` + `lucide-
 * <kebab-name>` merged into its className, independent of anything the
 * consuming component passes).
 *
 * That class alone is NOT unique on this page, though: three components
 * render a lucide `Users` icon inside `#range-main` — this MetaItem
 * (ExerciseOverviewRoute.tsx), the participants card in the stat-card row
 * directly below (ExerciseStatCardRow.tsx), and the persistent admin nav
 * (ExerciseShell.tsx). So we scope to `#range-main header` first: the
 * overview's metadata `<header>` closes before the stat-card row begins, and
 * ExerciseShell's nav is a `<nav>`, not a `<header>` — leaving exactly one
 * match. (`#range-main` is RangeLayout's main element, which also excludes
 * the platform-chrome Topbar; it is the same root the issue's own reported
 * DOM path starts from.)
 *
 * `.closest("div")` then walks up from the svg — past the icon's wrapping
 * `aria-hidden` span, which is not a div — to the MetaItem's own root div,
 * whose text is exactly the rendered value: the localized
 * "{count} participant(s)" string, or the "—" em-dash placeholder shown
 * while stats are loading/erroring (#2183's fix).
 *
 * `timeout` widens the retry window for callers that need to wait past the
 * em-dash placeholder to the resolved stats read (the lane's cold-boot-
 * tolerant idiom — see exercise-lifecycle.cy.ts's 30-45s windows on a
 * spec's first live call). It is applied to both the `cy.get` and the
 * `.closest` query so the whole chain shares one retry window — an
 * assertion chained off the returned subject takes its budget from the
 * LAST query, so passing it to `cy.get` alone would leave `.closest`
 * falling back to `defaultCommandTimeout`.
 */
export function exerciseOverviewParticipantsMeta(
  timeout?: number,
): Cypress.Chainable<JQuery<HTMLDivElement>> {
  const opts = timeout !== undefined ? { timeout } : undefined;
  return cy
    .get("#range-main header svg.lucide-users", opts)
    .closest("div", opts);
}

