}

/** The Porch feed column's composer trigger button (`PorchComposerTrigger`, #2944). */
export function porchComposerTrigger(): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.findByRole("button", { name: "What's on your mind?" });
}

