}

/**
 * The (capped-at-3) chip pills inside one row's chip row, resolved by
 * preset name (see `behavioralModelRow`). Chip VALUES are asserted in the
 * detail pane, not here — the row's job is only truncation.
 */
export function behavioralModelRowChips(
  name: string,
): Cypress.Chainable<JQuery<HTMLElement>> {
  return behavioralModelRow(name).find(
    '[data-testid="behavioral-model-row-chip"]',
