}

/** The persistent detail pane. */
export function behavioralModelDetailPane(): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.get('[data-testid="behavioral-models-detail-pane"]');
}

/** Every uncapped chip pill currently rendered in the detail pane. */
export function behavioralModelDetailChips(): Cypress.Chainable<JQuery<HTMLElement>> {
  return behavioralModelDetailPane().find(
    '[data-testid="behavioral-model-detail-chip"]',
  );

/**
 * ODIN-grounded exercise generation (#1724, Task 13). The drawer's
 * "Generate & Apply" CTA (`range_odin_generate_cta`,
 * `OdinTemplatePreviewDrawer.tsx`) — rendered only once the drawer's OWN
 * detail fetch has resolved to `"data"` (`showGenerateCta`, strictly
 * narrower than the "Use this environment" CTA's gate). Selected by
 * `data-testid`, not role/name: its accessible name ("Generate & Apply") is
 * IDENTICAL to the generation stepper's own `Dialog.Title` below, so a
 * role/name query alone can't tell the button from the dialog heading once
 * the stepper is mounted over the still-open drawer.
 */
export function odinGenerateCta(): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.get('[data-testid="odin-generate-cta"]');
}

/**
 * The live four-step generation stepper (`OdinGenerationStepper.tsx`) — a
 * route-level sibling rendered ABOVE the still-mounted picker/drawer stack
 * once a run starts (`open` tracks `odinFlow.phase.kind !== "idle"`). Its
 * `Dialog.Title` reads the SAME `range_odin_generate_cta` string as the CTA
 * button ("Generate & Apply"); disambiguated here by role (`dialog`, never
 * `button`).
 */
export function odinGenerationStepperDialog(
  timeout?: number,
): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.findByRole(
    "dialog",
    timeout !== undefined
      ? { name: "Generate & Apply", timeout }
      : { name: "Generate & Apply" },
  );
}

/** The four canonical step ids, in ladder order — mirrors range-mfe's own
 * `ODIN_GENERATION_STEPS` (`api/odin.ts`). Kept here as a literal union
 * rather than imported: this package never depends on range-mfe's source. */
export type OdinGenerationStepId =
  | "fetch_odin"
  | "generate_factions"
  | "analyze_environment"
  | "finalize_scenario";

/**
 * One row of the stepper's four-step ladder
 * (`[data-testid="odin-generate-step-<id>"]`), selected by its STRING step
 * id — NEVER by index/position. Each row also carries a `data-state`
 * attribute (`pending`/`running`/`done`/`failed`, `OdinGenerationStepper.tsx`'s
 * `StepLadder`); drive assertions off that attribute, never off the row's
 * (translated) label text.
 */
export function odinGenerationStep(
  id: OdinGenerationStepId,
): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.get(`[data-testid="odin-generate-step-${id}"]`);
}

/**
 * Every step-ladder row at once, for an atomic all-four-at-a-time assertion.
 * `OdinGenerationStepper`'s own completion effect closes the whole dialog the
 * moment its results start folding into the wizard draft
 * (`ExerciseSetupWizardRoute.applyGenerationResult`), so a run that finishes
 * fast enough can tear the ladder out of the DOM between two SEPARATE
 * `odinGenerationStep(id)` queries. Reading all four rows in one retryable
 * query (their common `data-testid` prefix) and asserting the whole set in a
 * single `.should(($rows) => ...)` callback avoids that race — Cypress
 * re-evaluates the callback against the CURRENT DOM on every retry, so it
 * only ever inspects a fully-consistent snapshot.
 */
export function odinGenerationSteps(
  timeout?: number,
): Cypress.Chainable<JQuery<HTMLElement>> {
  const opts = timeout !== undefined ? { timeout } : undefined;
  return cy.get('[data-testid^="odin-generate-step-"]', opts);
}

/**
 * The "replace the factions you have?" confirmation
 * (`ExerciseSetupWizardRoute.tsx`), surfaced only when a completed
 * generation run would otherwise clobber a non-empty `draft.factions` list
 * (`applyUpdate` routes that patch through `cascadeFactionListChange`, whose
 * "several removed, no 1:1" branch prunes allies/adversaries).
 */
export function odinGenerateReplaceConfirmDialog(): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.get('[data-testid="odin-generate-replace-confirm"]');
}



