/**
 * Single source of truth for the e2e suite's default test-user password.
 *
 * Must satisfy the realm's passwordPolicy (realm-export.json:
 * "length(12) and notUsername and passwordHistory(3)") — the Admin REST
 * reset-password endpoint enforces it, so any shorter literal re-hardcoded
 * elsewhere will start failing kcCreateUser / reset-password calls the moment
 * the policy changes. Import this constant instead of inlining the string.
 *
 * This module has zero node-only imports so it is safe to use from both the
 * browser (support/commands.ts, spec files) and the Node cy.task context
 * (support/personas.ts).
 */
export const DEFAULT_E2E_PASSWORD = "E2eTest1234!";


