/**
 * Cypress support entrypoint — loaded before every spec.
 *
 * - Registers @testing-library/cypress semantic queries (findByRole/Text/Label).
 * - Registers the shared commands (cy.login / cy.loginFresh / cy.skipIfStackDown).
 * - Global before(): requireLiveStack() — the whole suite runs against a LIVE
 *   compose stack. Locally we skip the spec when the stack is down (so a dev
 *   without the stack up isn't drowned in failures); in CI we FAIL HARD, because
 *   a down stack in CI is a real problem, not something to silently skip.
 */
import "@testing-library/cypress/add-commands";
import "./commands";

function shellBffUrl(): string {
  return (Cypress.env("SHELL_BFF_URL") as string) ?? "http://localhost:8082";
}

function isCI(): boolean {
  const ci = Cypress.env("CI");
  return ci === true || ci === "true" || ci === "1";
}

before(function requireLiveStack() {
  // The stack-free pseudolocale gate (`pnpm cypress:i18n`) runs against vite
  // preview servers only — no compose backend; every BFF read is stubbed via
  // cy.intercept. It passes `--env stackFree=true` so this guard doesn't demand
  // shell-bff. Every other spec still requires the live stack (hard-fail in CI).
  const stackFree = Cypress.env("stackFree");
  if (stackFree === true || stackFree === "true") return;
  cy.request({
    url: `${shellBffUrl()}/healthz`,
    failOnStatusCode: false,
    timeout: 5_000,
  }).then((res) => {
    if (res.status === 200) return;
    const msg = `Live stack is down: ${shellBffUrl()}/healthz returned ${res.status}.`;
    if (isCI()) {
      throw new Error(
        `${msg} The e2e suite requires the full compose stack in CI.`,
      );
    }
    // Local: skip the whole spec rather than fail — bring the stack up to run.
    cy.log(`${msg} Skipping (local, non-CI).`);
    this.skip();
  });
});


