 * `StepLadder`); drive assertions off that attribute, never off the row's
 * (translated) label text.
 */
export function odinGenerationStep(
  id: OdinGenerationStepId,
): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.get(`[data-testid="odin-generate-step-${id}"]`);
}

/**
 * Every step-ladder row at once, for an atomic all-four-at-a-time assertion.
 * `OdinGenerationStepper`'s own completion effect closes the whole dialog the
 * moment its results start folding into the wizard draft
 * (`ExerciseSetupWizardRoute.applyGenerationResult`), so a run that finishes
 * fast enough can tear the ladder out of the DOM between two SEPARATE
 * `odinGenerationStep(id)` queries. Reading all four rows in one retryable
 * query (their common `data-testid` prefix) and asserting the whole set in a
 * single `.should(($rows) => ...)` callback avoids that race — Cypress
 * re-evaluates the callback against the CURRENT DOM on every retry, so it
 * only ever inspects a fully-consistent snapshot.
 */
export function odinGenerationSteps(
  timeout?: number,
): Cypress.Chainable<JQuery<HTMLElement>> {
  const opts = timeout !== undefined ? { timeout } : undefined;
  return cy.get('[data-testid^="odin-generate-step-"]', opts);
}

/**
 * The "replace the factions you have?" confirmation
 * (`ExerciseSetupWizardRoute.tsx`), surfaced only when a completed
 * generation run would otherwise clobber a non-empty `draft.factions` list
 * (`applyUpdate` routes that patch through `cascadeFactionListChange`, whose
 * "several removed, no 1:1" branch prunes allies/adversaries).
 */
export function odinGenerateReplaceConfirmDialog(): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.get('[data-testid="odin-generate-replace-confirm"]');
}



